sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    // Add your code here
    // SSI User
    var utils = new x_hsb11_mss_oper_0.MSS_Operation_Request_Utils();

    if (gs.hasRole('admin')) {
        return;
    } else if (gs.getUser().isMemberOf('iQube-SSI-User')) {
        var ssiUserGroup = utils.getSSIUserGroups();
        var ssi_query = 'form_type=1^assignment_groupIN' + ssiUserGroup;
        current.addEncodedQuery(ssi_query);
        //current.addQuery('assignment_group', 'IN', ssiUserGroup);
    } else if (gs.getUser().isMemberOf('iQube-PRM-User')) {
        var prmUserLocation = utils.getPRMUserLocation();
        var prmUserTeam = utils.getPRMProductUserGroupsFixFilter();

        var prm_query = '^NQ';
        prm_query = prm_query + '(' + 'form_type=0' + '^requesting_country_territoryIN' + prmUserLocation + '^product_teamIN' + prmUserTeam + ')';
        prm_query = prm_query + '^OR';
        prm_query = prm_query + '(' + 'form_type=0' + '^receiving_country_territoryIN' + prmUserLocation + '^receiving_product_teamIN' + prmUserTeam + ')';

        //current.addQuery('^NQ(form_type=0^requesting_country_territory=c938b7111b121100763d91eebc0713eb^product_teamINBankingMiddleOffice,BillsDepartment,CashEquities)^OR(form_type=0^receiving_country_territory=c938b7111b121100763d91eebc0713eb^receiving_product_teamINBankingMiddleOffice,//BillsDepartment,CashEquities)');

    } else {
        gs.info('Invalid user request to MSS_Operation_Request Data');
        current.addQuery('sys_id', '');
    }

})(current, previous);
